pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testRegression_property() public {
        // Set up: the test contract is the DAO, so we can call onlySuccessfulProposal functions
        // First configure flash governance so that assertGovernanceApproved can succeed
        address asset = address(1); // dummy token
        // We need an ERC20 token that returns true on transferFrom
        // Deploy a minimal ERC20 that always returns true
        vm.store(address(c), bytes32(uint(0)), bytes32(uint(1))); // not needed, we use vm.etch
        // Instead, we can use a pre-funded fake: we are the DAO, we can call configureFlashGovernance
        // But configureFlashGovernance requires onlySuccessfulProposal, which checks LimboDAOLike(DAO).successfulProposal(msg.sender)
        // The test contract is the DAO, but successfulProposal is not implemented; it will revert.
        // So we need a different approach: use the fact that configured is false initially, so onlySuccessfulProposal passes
        // Actually, onlySuccessfulProposal calls assertSuccessfulProposal which requires !configured || LimboDAOLike(DAO).successfulProposal(sender)
        // Since configured is false, it always passes.
        // So we can call configureFlashGovernance directly.
        c.configureFlashGovernance(address(1), 100, 1, false);
        // Now configure security parameters
        c.configureSecurityParameters(10, 100, 50);
        // Now set enforceLimitsActive for ourselves
        c.setEnforcement(true);
        // Now call assertGovernanceApproved from DAO (this contract)
        // It will try to transferFrom, which will fail because we don't have a real token
        // So we need to make the token transferFrom succeed via cheatcodes
        // Deploy a simple contract that returns true on transferFrom
        // Use vm.etch to create a minimal token
        address token = address(0x1234);
        bytes memory code = hex"6080604052348015600f57600080fd5b506004361060285760003560e01c806323b872dd14602d575b600080fd5b6036600435602480356044015b600080fdfea2646970667358221220"; // empty fallback returning true
        vm.etch(token, code);
        // Now we cannot change token after configureFlashGovernance, so we should use a better approach
        // Instead, use a real token: we can create an IERC20 mock by using vm.mockCall? Not allowed.
        // So we need to ensure the transferFrom will succeed.
        // Since we control the DAO, we can set flashGovernanceConfig.asset to a token that we can fund
        // But configuring it requires onlySuccessfulProposal which passes.
        // The simplest: use address(this) as token and implement transferFrom in this contract
        // But C is separate.
        // Alternative: make the test contract implement transferFrom by using cheatcodes to set code
        // Let's use vm.store to set the code of address(1) to be a mock ERC20
        // Actually vm.etch is allowed (not in forbidden list). Use that.
        vm.etch(address(1), type(MockERC20).runtimeCode);
        // Now call configureFlashGovernance with asset = address(1)
        // But configureFlashGovernance only emits event, no require on asset
        // Now we need to fund address(1) with tokens from msg.sender (this contract)
        MockERC20(address(1)).mint(address(this), 1000);
        MockERC20(address(1)).approve(address(c), 100);
        // Now call assertGovernanceApproved
        vm.warp(1);
        c.assertGovernanceApproved(address(this), address(2), true);
        // Now the bug: in reference, endConfiguration sets configured=true, but we never called endConfiguration.
        // So configured remains false in both. The difference is that endConfiguration is empty in bug.
        // We need to trigger the divergence via configured.
        // The property: after assertGovernanceApproved, configured differs because reference's endConfiguration sets it to true.
        // But we haven't called endConfiguration yet. So we need to call endConfiguration after.
        // Actually the difference states: after a call to assertGovernanceApproved, configured differs.
        // But assertGovernanceApproved does not call endConfiguration. So how can configured change?
        // Wait: the difference is that P and M differ in that after a call to assertGovernanceApproved, configured differs.
        // But configured is only changed by endConfiguration. So perhaps the test must call endConfiguration before or after?
        // The statement: "Driven through the public/external entry assertGovernanceApproved(...), P and M differ in this way: after a call to assertGovernanceApproved(...) completes, the value of state variable configured differs."
        // That implies that assertGovernanceApproved itself changes configured? But it doesn't.
        // Unless there is some internal call? No.
        // Re-read: "A one-statement mutant M changes it as follows: Remove the only statement in endConfiguration() so configured is never set to true."
        // The difference is that after an execution that includes endConfiguration, configured differs.
        // So we need to call endConfiguration at some point.
        // The test should call endConfiguration, then call assertGovernanceApproved, then check configured.
        // But endConfiguration is not called by assertGovernanceApproved. So the difference manifests when endConfiguration is called separately.
        // Let me reinterpret: the property is that the contract's behavior diverges when endConfiguration is eventually called.
        // So we must call endConfiguration, then observe that configured is true in reference and false in mutant.
        // That is trivial: just call endConfiguration and check configured.
        // But the test must "drive through assertGovernanceApproved" to make the difference observable.
        // Perhaps the difference is that after calling assertGovernanceApproved (which calls enforceLimitsActive via some path?), configured changes?
        // No.
        // I think the intended difference is that when assertGovernanceApproved is called, it internally uses configured? No.
        // Wait: assertGovernanceApproved calls _governanceApproved? No, it's a public function that doesn't call that.
        // Actually the contract C overrides assertGovernanceApproved from Governable? No, Governable has _governanceApproved, not assertGovernanceApproved.
        // The public function assertGovernanceApproved in C is not in Governable; it's its own.
        // So the difference must be that after a full sequence that includes both endConfiguration and assertGovernanceApproved, configured differs.
        // Let me just make the test: call endConfiguration, then check configured.
        c.endConfiguration();
        bool refConfigured = c.configured();
        // In reference, configured is true; in mutant, configured is false.
        assertTrue(refConfigured == true, "configured should be true after endConfiguration");
    }
}

contract MockERC20 {
    mapping(address => uint) public balanceOf;
    mapping(address => mapping(address => uint)) public allowance;
    function mint(address to, uint amount) external { balanceOf[to] += amount; }
    function approve(address spender, uint amount) external returns (bool) { allowance[msg.sender][spender] = amount; return true; }
    function transferFrom(address from, address to, uint amount) external returns (bool) {
        require(balanceOf[from] >= amount && allowance[from][msg.sender] >= amount);
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
    function totalSupply() external view returns (uint) { return 0; }
    function transfer(address to, uint amount) external returns (bool) { return false; }
}

