pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        c = new C(address(this));
    }
    function testRegression_property() public {
        // Deploy a helper contract that calls enforceTolerance
        EnforceCaller helper = new EnforceCaller();

        // Set up DAO (the test contract itself) to call assertGovernanceApproved
        vm.prank(address(this));
        c.configureFlashGovernance(address(0x1), 100, 1000, false);

        // Set security parameters with changeTolerance = 50
        vm.prank(address(this));
        c.configureSecurityParameters(1, 1, 50);

        // End configuration (reference sets configured=true, buggy does not)
        vm.prank(address(this));
        c.endConfiguration();

        // Set enforceLimitsActive for the helper contract
        vm.prank(address(helper));
        c.setEnforcement(true);

        // Give helper an ERC20 token to pass transferFrom check in assertGovernanceApproved
        // Simulate by deploying a mock ERC20 that returns true on transferFrom
        // But we can use address(0x1) as asset, but transferFrom will revert because no code
        // Instead, we use a real ERC20 mock deployed
        // Since we cannot deploy another contract, we use address(0x01) and deal tokens
        // Actually, the asset address must have code, so we deploy a simple one
        // For simplicity, we just call assertGovernanceApproved from DAO (address(this))
        // which bypasses the transferFrom requirement because DAO is allowed by flashEnabled modifier

        // Now call assertGovernanceApproved from this contract (which is DAO)
        vm.prank(address(this));
        // This call should succeed because DAO is flashEnabled
        c.assertGovernanceApproved(address(this), address(helper), false);

        // Now call enforceTolerance from helper: reference reverts (configured=true, enforcement active)
        // buggy does not revert (configured=false, returns early)
        bool ok;
        try helper.callEnforceTolerance(address(c), 100, 90) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference (correct) should revert, so ok=false
        // The buggy (incorrect) should not revert, so ok=true
        // We assert false because we expect revert (ok=false) on correct
        assertTrue(!ok, "Expected revert from enforceTolerance but got success");
    }
}

contract EnforceCaller {
    function callEnforceTolerance(address cAddr, uint256 v1, uint256 v2) external returns (bool) {
        C(cAddr).enforceTolerance(v1, v2);
        return true;
    }
}

