        Helper helper = new Helper(address(c));
        c.configureFlashGovernance(address(helper), 1, 1, false);
        c.setGoverned(new address[](0), new bool[](0)); // dummy call to satisfy setGoverned being onlySuccessfulProposal, but we have no proposals so skip; instead we make helper governed via DAO
        // DAO (this test contract) sets helper as governed
        address[] memory govs = new address[](1);
        govs[0] = address(helper);
        bool[] memory govsBool = new bool[](1);
        govsBool[0] = true;
        c.setGoverned(govs, govsBool);
        // endConfiguration to set configured=true in reference
        c.endConfiguration();
        // Now call assertGovernanceApproved from helper, which is governed
        vm.prank(address(helper));
        c.assertGovernanceApproved(address(helper), address(0), true);
        // Helper contract calls enforceTolerance with v1=2, v2=1 -> in reference, revert; in bug, no revert
        bool ok;
        try helper.callEnforceTolerance(2, 1) {
            ok = true;
        } catch {
