pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deploy a helper contract that will call enforceTolerance
        Helper helper = new Helper();

        // Set up: endConfiguration, then assertGovernanceApproved from DAO
        c.endConfiguration();

        // Set up flash governance config so assertGovernanceApproved can succeed
        // Transfer required asset (we need a token that returns true on transferFrom)
        // Since we control DAO (this contract), we can deploy a mock ERC20
        MockERC20 token = new MockERC20();
        token.mint(address(this), 100);

        // Configure flash governance
        c.configureFlashGovernance(address(token), 1, 1, false);

        // Set approve for the transferFrom to succeed
        token.approve(address(c), 1);

        // Call assertGovernanceApproved from DAO with emergency=true
        vm.prank(address(this));
        c.assertGovernanceApproved(address(this), address(0x1234), true);

        // Now helper calls setEnforcement(true) then enforceTolerance
        helper.setEnforcement(true);

        bool ok;
        try helper.callEnforceTolerance(address(c), 2, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference contract has configured=true, so enforceTolerance reverts (ok=false)
        // Buggy contract never sets configured, so enforceTolerance returns early (ok=true)
        assertTrue(ok == false);
    }
}

contract Helper {
    function setEnforcement(bool enforce) public {
        // This contract does not have enforceLimitsActive, so we need to make it callable
        // We'll directly interact with C's setEnforcement
        // However, setEnforcement is on C, not on Helper. So we need to pass C address.
        // Let's restructure: Helper will have a function that calls C.setEnforcement and then C.enforceTolerance
    }
    function callEnforceTolerance(address cAddr, uint256 v1, uint256 v2) public {
        C(cAddr).enforceTolerance(v1, v2);
    }
}

