// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up a non-DAO governed caller
        address caller = address(0x123);

        // Set DAO to self and enable governance for caller
        c.setDAO(address(this));
        vm.startPrank(address(this));
        address[] memory governables = new address[](1);
        governables[0] = caller;
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);
        vm.stopPrank();

        // Configure flash governance with a mock asset and amount
        address mockAsset = address(0x456);
        vm.prank(address(this));
        c.configureFlashGovernance(mockAsset, 100, 1, false);

        // End configuration
        c.endConfiguration();

        // Now caller attempts assertGovernanceApproved with target = address(this)
        vm.startPrank(caller);
        bool success;
        try c.assertGovernanceApproved(caller, address(this), false) {
            success = true;
        } catch {
            success = false;
        }
        vm.stopPrank();

        // In reference (configured=true): caller is not a successful proposal, so _governanceApproved reverts -> success=false, pendingFlashDecision remains empty
        // In bug (configured=false): configured check bypassed, governance logic runs, pendingFlashDecision set for target->caller
        ( , , uint256 unlockTime) = c.pendingFlashDecision(address(this), caller);
        assertTrue(unlockTime == 0);
    }
}

