pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Configure flash governance so that assertGovernanceApproved can succeed
        vm.prank(address(this));
        c.configureFlashGovernance(address(0x1), 100, 1, false);

        // Mark target and caller as governed
        address target = address(0x2);
        address caller = address(0x3);
        address[] memory govs = new address[](2);
        govs[0] = target;
        govs[1] = caller;
        bool[] memory isGov = new bool[](2);
        isGov[0] = true;
        isGov[1] = true;
        vm.prank(address(this));
        c.setGoverned(govs, isGov);

        // Call endConfiguration() to set configured = true (reference) or false (bug)
        c.endConfiguration();

        // Give caller some asset and approve
        vm.deal(caller, 200);
        vm.prank(caller);
        // Since we are not using real ERC20, we rely on transferFrom returning true
        // Actually we need an ERC20 token; we'll use address(this) as token
        // But easier: we use the fact that the contract itself has no real token
        // Instead we'll use a mock: just ensure transferFrom returns true
        // We'll deploy a minimal token mock
        // However simpler: we just call assertGovernanceApproved and check pendingFlashDecision

        // The bug: after endConfiguration() sets configured=false, caller is governed
        // so flashEnabled modifier passes, and the governance logic proceeds
        // Reference: configured=true, so _governanceApproved is called, which calls
        // assertSuccessfulProposal(caller) and reverts because caller is not a successful proposal

        // We wrap the call in try/catch to capture revert
        bool ok = true;
        vm.prank(caller);
        try c.assertGovernanceApproved(target, caller, false) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, check pendingFlashDecision[target][caller].amount
        // In reference (configured=true), the call reverts so amount stays 0
        // In bug (configured=false), the call succeeds and amount becomes the flash governance config amount (100)
